diff --git a/src/window.js b/src/window.js
index 4c5c0e2..56f4926 100644
--- a/src/window.js
+++ b/src/window.js
@@ -11,18 +11,31 @@ export function findIndex(offsets, y) {
   return lo;
 }

+// Largest i with offsets[i] < y (a row whose top sits exactly on y is not visible).
+function findLastBefore(offsets, y) {
+  const count = offsets.length - 1;
+  let lo = 0;
+  let hi = count - 1;
+  while (lo < hi) {
+    const mid = (lo + hi + 1) >> 1;
+    if (offsets[mid] < y) lo = mid;
+    else hi = mid - 1;
+  }
+  return lo;
+}
+
 // Rows to render as a half-open range [start, end).
 // The sticky header covers the top `headerHeight` px of the viewport, so the body is visible
 // from y = scrollTop to y = scrollTop + viewport - headerHeight (exclusive).
 export function computeRange({ offsets, scrollTop = 0, viewport = 0, headerHeight = 0, overscan = 0 }) {
   const count = offsets.length - 1;
   if (count <= 0) return { start: 0, end: 0 };
-  const top = Math.max(0, scrollTop - headerHeight);
-  const bottom = scrollTop + viewport;
+  const top = scrollTop;
+  const bottom = scrollTop + viewport - headerHeight;
   const first = findIndex(offsets, top);
-  const last = findIndex(offsets, Math.max(top, bottom));
+  const last = findLastBefore(offsets, Math.max(top, bottom));
   return {
     start: Math.max(0, first - overscan),
-    end: last + 1 + overscan,
+    end: Math.min(count, last + 1 + overscan),
   };
 }
